LIMIT #{startIndex},#{pageSize}

select count(1) from t_group_xiaohao_history
where group_id = #{groupId} and hehuoren_id = #{hehuorenId}

  and profit_time >= #{startTime}


  and profit_time <= #{endTime}


  and player_id = #{searchUid}

select ifnull(SUM(profit),0) from t_group_xiaohao_history
where group_id = #{groupId} and hehuoren_id = #{hehuorenId}

  and profit_time >= #{startTime}


  and profit_time <= #{endTime}


  and player_id = #{searchUid}
